import{_ as o,o as t,c as i,ag as a}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-09-16（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-09-16.md","filePath":"topics/biomedicine/science-daily-2026-09-16.md"}'),l={name:"topics/biomedicine/science-daily-2026-09-16.md"};function r(c,e,n,u,s,d){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="科学日报-·-2026-09-16-生物医学" tabindex="-1">科学日报 · 2026-09-16（生物医学） <a class="header-anchor" href="#科学日报-·-2026-09-16-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-09-16（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> — 第27期</p></blockquote><hr><h2 id="rnf213-直接泛素化糖原-大脑多聚葡聚糖的质量控制-nature" tabindex="-1">RNF213 直接泛素化糖原：大脑多聚葡聚糖的质量控制（Nature） <a class="header-anchor" href="#rnf213-直接泛素化糖原-大脑多聚葡聚糖的质量控制-nature" aria-label="Permalink to &quot;RNF213 直接泛素化糖原：大脑多聚葡聚糖的质量控制（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ DOI: 10.1038/s41586-026-11139-6</p></blockquote><ul><li>背景：生物大分子质控长期聚焦 DNA 修复与蛋白质错误折叠，<strong>糖原这类储能多糖如何被监控一直不清</strong>；异常分支稀少的糖原聚成不溶性多聚葡聚糖体（polyglucosan）可致严重脑病。</li><li>机制：E3 泛素连接酶 <strong>RNF213</strong> 选择性泛素化异常糖原 → 招募自噬受体 SQSTM1、TAX1BP1、optineurin → 进入自噬体降解，构成&quot;糖原自噬&quot;质控通路；缺失 RNF213 连接酶活性小鼠在小脑/脑桥/海马堆积 polyglucosan。</li><li>结构：冷冻电镜示 RNF213 的 CBM20 结构域结合线性寡糖（糖原衍生麦芽七糖），破坏该结合会&quot;解锁&quot;其生理糖原活性——CBM20 起到闸门作用。</li><li>上位分析：RNF213 位于 <strong>LUBAC 上游</strong>，提示存在一个由多个 E3 连接酶组成、分层执勤的糖原质控网络。</li><li>洞察：把&quot;泛素化→自噬降解&quot;这套机制首次推广到**非蛋白大分子（糖原）**的质控——延续本主题&quot;靶向降解/分子胶&quot;主线，但对象从蛋白扩到多糖，是降解生物学的新边界。</li></ul><h2 id="编码性与非遗传蛋白变体-扩展人类功能蛋白质组-nature" tabindex="-1">编码性与非遗传蛋白变体：扩展人类功能蛋白质组（Nature） <a class="header-anchor" href="#编码性与非遗传蛋白变体-扩展人类功能蛋白质组-nature" aria-label="Permalink to &quot;编码性与非遗传蛋白变体：扩展人类功能蛋白质组（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ DOI: 10.1038/s41586-026-11124-z</p></blockquote><ul><li>中心法则每一环节（杂合性、体细胞突变、转录错误、翻译错误）都贡献蛋白变体，但缺乏系统检测/定量/功能评估方法。</li><li>数据：29 个健康组织蛋白质基因组大数据 → 13,910 个可靠定位变体，对应 <strong>7,215 种单一氨基酸替换</strong>，与参考蛋白同时共存。</li><li>发现：非遗传（翻译错误产生）替换丰度与人群等位基因频率平行；且能<strong>绕过遗传密码的突变约束</strong>，为探索蛋白序列空间提供独立路径；氨基酸饥饿下癌系细胞呈现特异的、可重复的非遗传变异模式。</li><li>提议：这批替换构成一类新的人体蛋白&quot;扩展形态&quot;；并实验验证了特定非遗传替换对纯化蛋白的功能影响。</li><li>洞察：蛋白质组的多样性远超&quot;基因编码&quot;这一层，<strong>翻译错误也是可调控的功能来源</strong>——对蛋白质组学、肿瘤异质性与&quot;序列空间可探索性&quot;都有方法论意义，衔接基因组/表观到蛋白组的功能基因组主线。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第27期 科学板块</p></blockquote>',11)])])}const _=o(l,[["render",r]]);export{p as __pageData,_ as default};
